    body { margin: 0; background: #f4f6fa; color: #18243b; font-family: system-ui, sans-serif; }
    main { max-width: 760px; margin: 60px auto; padding: 32px; background: white; border-radius: 12px; box-shadow: 0 4px 24px #18243b0c; }
